INSERT INTO `departments` VALUES
(1,'Computing and Informatics','academic','Department of ICT offering courses in software development, networking, and computer applications to prepare students for the digital economy.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1782269695/kigumo-tvc/departments/gaup8gc0jorbqnpmloow.jpg','To be a Centre of excellence in ICT training, producing innovative and skilled professionals who drive Kenya\'s digital transformation.','To provide high-quality, competency-based ICT training that equips learners with cutting-edge technical skills for the digital economy.','To produce graduates proficient in software development, networking, database management, and emerging technologies who can compete globally.','2026-05-21 06:58:23','2026-06-27 19:25:54'),
(2,'Business Studies','academic','Department of Business Studies providing training in accounting, secretarial studies, and business management for the corporate world.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781016252/kigumo-tvc/departments/zegk1bj74xbea6eo8bti.jpg','To be a leading Centre of excellence in business and entrepreneurship training, producing ethical and self-driven professionals.','To provide high-quality, competency-based business training that nurtures creativity, fosters enterprise development, and empowers trainees with relevant skills.','To equip learners with practical business and entrepreneurial competencies that promote job creation, ethical leadership, and economic empowerment.','2026-05-21 06:58:23','2026-06-09 14:44:13'),
(3,'Engineering & Technical Studies','academic','Department of Engineering offering hands-on training in electrical, mechanical, and civil engineering technologies.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781016190/kigumo-tvc/departments/hp6daipq69zjgdgw5aoc.jpg','To be a Centre of excellence in engineering and technical training, producing skilled technicians who drive industrial growth.','To provide practical, hands-on engineering training that meets industry standards and prepares trainees for the technical workforce.','To produce competent engineers and technicians capable of designing, maintaining, and innovating in the engineering sector.','2026-05-21 06:58:23','2026-06-09 14:43:11'),
(7,'Sports & Games','non_academic','Department of Sports coordinating all college sports activities.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781016218/kigumo-tvc/departments/mfewdoignjtkv3d4o0n1.jpg','To be a Centre of sporting excellence, nurturing talent and promoting healthy lifestyles among students.','To provide quality sports training and facilities that develop athletic talent, teamwork, and physical fitness.','To produce well-rounded students who excel both academically and in sports, representing the college at county and national levels.','2026-05-21 06:58:23','2026-06-09 14:43:39'),
(8,'Clubs & Societies','non_academic','Department overseeing student clubs and societies.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781022762/kigumo-tvc/departments/r9jhm53jkfbnmehpskti.jpg','To be a vibrant hub of student engagement, fostering leadership, creativity, and social responsibility.','To provide a platform for students to explore their talents, develop leadership skills, and engage in meaningful extracurricular activities.','To nurture holistic student development through diverse clubs and societies that complement academic learning.','2026-05-21 06:58:23','2026-06-09 16:32:42'),
(9,'Fashion And Design','academic','Department for Fashion And Design','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781022784/kigumo-tvc/departments/v4z2dowfrlxqkgcvdubm.jpg','To provide a comfortable, safe, and supportive living environment that enhances the student experience.','To deliver quality catering and accommodation services that meet the nutritional and residential needs of students.','To ensure every student has access to clean, affordable accommodation and nutritious meals throughout their studies.','2026-05-21 06:58:23','2026-06-09 16:33:05'),
(10,'Guidance & Counseling','non_academic','The Guidance and Counselling Department at Kigumo Technical and Vocational College is committed to promoting the academic, social, emotional, and personal well-being of trainees. The department provides professional guidance, counselling, mentorship, and career development services aimed at helping students make informed decisions, overcome challenges, develop positive values, and achieve their full potential in both their academic and personal lives.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781022487/kigumo-tvc/departments/vv7tnzg08f0crhpi2zlf.jpg','To be a Centre of student support, promoting mental wellness, personal growth, and academic success.','To provide professional guidance and counseling services that support students\' emotional, psychological, and career development.','To empower students with the resilience, self-awareness, and decision-making skills needed to navigate academic and personal challenges.','2026-05-21 06:58:23','2026-06-24 11:01:12'),
(60002,'Research, Innovation & Linkages','non_academic','The Department of Research, Innovation and Linkages coordinates all college research activities, fosters innovation among students and staff, manages industry partnerships, and facilitates knowledge exchange through conferences, publications, and collaborative projects with local and international institutions.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1781022748/kigumo-tvc/departments/f6cv8yygzg5whvfocmxm.jpg','To be a hub of research excellence, driving innovation and fostering partnerships that benefit the college and community.','To coordinate research activities, promote innovation, and build linkages with industry, government, and international partners.','To create a culture of research and innovation that produces solutions to local and national challenges.','2026-06-09 11:11:45','2026-06-09 16:32:28'),
(120002,'Building And Civil Engineering ','academic','The Building and Civil Engineering Department at Kigumo Technical and Vocational College is dedicated to producing competent, innovative, and industry-ready professionals in the construction sector. The department equips trainees with practical and theoretical skills in building technology, civil engineering works, surveying, construction management, materials testing, and sustainable infrastructure development. Through competency-based training, modern workshops, and industry partnerships, the department prepares graduates to meet the growing demands of Kenya\'s construction and infrastructure sectors.','https://res.cloudinary.com/dabo8y2bw/image/upload/v1782297669/kigumo-tvc/departments/rgiohgkypwve3odx4cj7.jpg','To be a center of excellence in Building and Civil Engineering training, producing highly skilled, innovative, and globally competitive professionals for sustainable infrastructure development.','To provide quality competency-based education and training in Building and Civil Engineering through practical skills development, innovation, research, and industry collaboration for socio-economic transformation.','To provide quality training that meets TVET and industry standards.\r\nTo equip trainees with practical and employable construction skills.\r\nTo promote innovation and technology adoption in the construction industry.\r\nTo enhance research and problem-solving skills among trainees.\r\nTo strengthen partnerships with industry for industrial attachment and employment opportunities.\r\nTo promote sustainable and environmentally friendly construction practices.\r\nTo ensure graduates are competent, ethical, and productive professionals.\r\nTo support national development through the training of skilled manpower in the building and civil engineering sector.','2026-06-24 10:41:09','2026-06-25 18:11:04'),
(150002,'Electrical and Electronic Engineering','academic','Department offering comprehensive training in electrical installation, electronics, and power systems.',NULL,'To be a center of excellence in electrical and electronic engineering training in Kenya.','To produce competent, innovative, and industry-ready electrical technicians and engineers.','To equip learners with practical electrical skills, safety standards, and modern electronic technologies.','2026-06-27 19:19:11','2026-06-27 19:19:11'),
(150003,'Automotive and Mechanical Engineering','academic','Department focused on mechanical engineering, automotive technology, welding, and fabrication.',NULL,'To be a leading provider of mechanical and automotive engineering skills in the region.','To deliver hands‑on, competency‑based training that meets industrial demands.','To train skilled technicians in automotive repair, production technology, and metal fabrication.','2026-06-27 19:19:11','2026-06-27 19:19:11'),
(150004,'Cosmetology and Beauty Therapy','academic','Department offering hair dressing, beauty therapy, and cosmetology courses at all levels.',NULL,'To be a centre of excellence in beauty and cosmetology training.','To provide quality competency‑based training that produces creative and professional beauty therapists.','To equip learners with advanced hair, skin, and beauty care skills.','2026-06-27 19:19:11','2026-06-27 19:19:11'),
(150005,'Hospitality and Food Beverage','academic','Department specializing in food production, beverage service, and hospitality management.',NULL,'To be a premier hospitality training institution in the region.','To deliver world‑class training in culinary arts, food safety, and customer service.','To produce skilled chefs, waiters, and hospitality managers for the tourism industry.','2026-06-27 19:19:11','2026-06-27 19:19:11'),
(150006,'Agriculture and Agribusiness','academic','Department offering training in agricultural production, agribusiness, and sustainable farming.',NULL,'To be a leader in agricultural training and agribusiness innovation.','To produce skilled agriculturalists and agribusiness entrepreneurs.','To equip learners with modern farming techniques, animal husbandry, and agribusiness management skills.','2026-06-27 19:19:11','2026-06-27 19:19:11');
